from PIL import Image
import numpy as np
A=np.array(Image.open('/app/output/main_top_canvas_cam.png').convert('RGB'))
g=A.mean(2)
m=g<80
# components 8-connected pure py
H,W=m.shape;seen=np.zeros_like(m);cc=[]
for r,c in zip(*np.nonzero(m)):
 if seen[r,c]:continue
 st=[(r,c)];seen[r,c]=1;pts=[]
 while st:
  y,x=st.pop();pts.append((y,x))
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    yy,xx=y+dy,x+dx
    if 0<=yy<H and 0<=xx<W and m[yy,xx] and not seen[yy,xx]:seen[yy,xx]=1;st.append((yy,xx))
 if len(pts)>5:cc.append(np.array(pts))
print([(len(p),(p[:,1].min(),p[:,0].min(),p[:,1].max(),p[:,0].max()),p.mean(0)) for p in cc])
# convert char component pixels to target coords
for p in cc:
 if p[:,0].mean()<500:
  rc=np.c_[(p[:,0]-512)/.866+511.5,(p[:,1]-512)/.866+511.5]
  print('target-equivalent bbox row,col',rc.min(0),rc.max(0),'centroid',rc.mean(0))
PY

python - <<'PY'
from PIL import Image
import numpy as np
A=np.array(Image.open('/app/output/main_frame_canvas.png').convert('L'))<80
rr,cc=np.indices(A.shape);tr=np.rint((rr-512)/.866+511.5).astype(int);tc=np.rint((cc-512)/.866+511.5).astype(int)
valid=A&(rr>=68)&(rr<956)&(cc>=68)&(cc<956)&(tr>=0)&(tr<1024)&(tc>=0)&(tc<1024)
actual=np.zeros((1024,1024),bool);actual[tr[valid],tc[valid]]=1
T=np.array(Image.open('/app/target.png').convert('L'))<100
for name,M in [('actual',actual),('target',T)]:
 y,x=np.where(M);print(name,(y.min(),x.min(),y.max(),x.max()),len(x))
# color component overview bounds by raster zones
for name,(a,b) in [('top',(180,290)),('left',(250,500)),('base',(450,550)),('hook',(500,820))]:
 for M,N in [(actual,'actual'),(T,'target')]:
  y,x=np.where(M[a:b]);
  if len(x):print(name,N,'box',y.min()+a,x.min(),y.max()+a,x.max())
